/// <summary>
/// Extension of table InventLoaction
/// </summary>
[ExtensionOf(tableStr(InventLocation))]
final class AVAInventLocationDbt_Extension
{
}

Method.Source:
/// <summary>
/// Extension of method modifiedField
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(InventLocation, AVAPOTransfer):
            if(this.AVAPOTransfer)
            {
                this.Manual = NoYes::Yes;
            }
            break;

        case fieldNum(InventLocation, AVAAutoShippingProcess ):
            if(!this.AVAAutoShippingProcess)
            {
                this.AVAAutoPackingSlipProcess = NoYes::No;
                this.AVAAutoBillofLoadingProcess = NoYes::No;
            }
            break;
    }
}

/// <summary>
///     AVA <c>validateWrite</c> method.
///     AVA - Schneider 16.02.2024
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean validateWrite()
{
    boolean retVal;

    WMSLocationIdDefaultReturn locWMSLocationIdDefaultReturn;

    // avoid check in this.validateDefaultReturnCreditOnlyLocation()
    if(this.DefaultReturnCreditOnlyLocation != '')
    {
        locWMSLocationIdDefaultReturn           = this.DefaultReturnCreditOnlyLocation;
        this.DefaultReturnCreditOnlyLocation    = '';
    }

    retVal = next validateWrite();

    if(locWMSLocationIdDefaultReturn != '')
    {
        this.DefaultReturnCreditOnlyLocation = locWMSLocationIdDefaultReturn;
    }

    return retVal;
}
